Consider the following generic stack class and its usage:

class GenericStack<T> {
    private java.util.List<T> items = new java.util.ArrayList<>();
    public void push(T item) { items.add(item); }
    public T pop() { return items.remove(items.size() - 1); }
}

public class Test {
    public static void main(String[] args) {
        GenericStack<String> gs = new GenericStack<>();
        gs.push("Hello");

        GenericStack<Integer> gi = new GenericStack<>();
        gi.push(36);

        System.out.println(gs.pop() + " " + gi.pop());
    }
}

